const execFileAsync = promisify(execFile)

const acceptanceSchema: ObjectJsonSchema = {
  type: 'object',
  additionalProperties: false,
  required: ['checks'],
  properties: {
    checks: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['id', 'status', 'reason'],
        properties: {
          id: { type: 'string' },
          status: { type: 'string', enum: ['fixed', 'open'] },
          reason: { type: 'string' },
        },
      },
    },
  },
}

interface AcceptanceCheck {
  id: string
  status: 'fixed' | 'open'
  reason: string
}

async function git(args: string[], signal: AbortSignal): Promise<string> {
  const { stdout } = await execFileAsync('git', args, { cwd: process.cwd(), signal, encoding: 'utf8', maxBuffer: 16 * 1024 * 1024 })
  return stdout.trim()
}

async function gateBase(signal: AbortSignal): Promise<{ base?: string; baseSha: string; root: string }> {
  const root = await git(['rev-parse', '--show-toplevel'], signal)
  try {
    const base = await git(['rev-parse', '--abbrev-ref', '--symbolic-full-name', '@{upstream}'], signal)
    const baseSha = await git(['rev-parse', base], signal)
    return { base, baseSha, root }
  } catch {
    const baseSha = await git(['rev-parse', 'HEAD'], signal)
    return { baseSha, root }
  }
}

async function isAncestor(ancestor: string, head: string, signal: AbortSignal): Promise<boolean> {
  try {
    await git(['merge-base', '--is-ancestor', ancestor, head], signal)
    return true
  } catch {
    return false
  }
}

function gitPushCommand(arguments_: unknown): boolean {
  if (!arguments_ || typeof arguments_ !== 'object') return false
  const command = (arguments_ as { command?: unknown }).command
  if (typeof command !== 'string') return false
  return /(?:^|[;&|]\s*)\s*(?:\w+=\S+\s+)*git(?:\s+(?:-C\s+\S+|-c\s+\S+|--git-dir(?:=\S+|\s+\S+)|--work-tree(?:=\S+|\s+\S+)))*\s+push(?:\s|$)/.test(command)
}

function openFindings(episode: GateEpisode): GateFinding[] {
  return episode.findings.filter(finding => finding.status === 'open')
