}

async function acceptDiff(
  ctx: Context,
  config: JuryConfig,
  parent: Agent,
  episode: GateEpisode,
  diff: string,
  signal: AbortSignal,
): Promise<AcceptanceCheck[]> {
  const frozen = episode.findings.map(({ id, file, line, title, fix }) => ({ id, file, line, title, fix }))
  const prompt = `You are a lightweight acceptance agent, not a reviewer. Compare the new diff only with the frozen finding set F. For every id in F, decide fixed when the new diff resolves that exact issue and open otherwise. A finding stays fixed when the diff does not touch it or fixes it with semantically equivalent code. Only mark open when the exact defect remains in the new diff or is explicitly reintroduced; do not reopen merely because the fix differs from your preferred implementation. Return every id once with a short reason. Do not report new problems, do not add findings, do not use tools, and do not return prose outside the structured result.\nFrozen F:\n${JSON.stringify(frozen, null, 2)}\nNew diff:\n${diff}`
  const activation = await ctx.subagents.startActivation({
    provider: 'spawn',
    label: `jury-acceptance-${episode.round + 1}`,
    request: {
      prompt: [{ type: 'text', text: prompt }],
      parent,
      outputSchema: acceptanceSchema,
      agentOptions: { maxTokens: config.agentMaxTokens },
      maxDepth: 1,
    },
    signal,
    delivery: 'caller',
  })
